namespace App\Filament\Imports;

use App\Models\Induk;
use App\Models\Character;
use Filament\Actions\Imports\ImportColumn;
use Filament\Actions\Imports\Importer;
use Filament\Actions\Imports\Models\Import;
use Illuminate\Support\Number;
use Filament\Forms\Components\Checkbox;

/**
 * Generated importer for Induks rows from CSV/XLSX.
 */
class IndukImporter extends Importer
{
    protected static ?string $model = Induk::class;

    /**
     * Mappable import columns with type casts and rules.
     * @return  array  ImportColumn definitions.
     */
    public static function getColumns(): array
    {
        return [
            ImportColumn::make('id')
                ->label('ID')
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['nullable', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('ID'),

            ImportColumn::make('nama_induk')
                ->label('Parent Name')
                ->requiredMapping()
                ->ignoreBlankState()
                ->rules(['required', 'max:255'])
                ->examples(['Sample Parent Name 1', 'Sample Parent Name 2'])
                ->exampleHeader('Parent Name'),

            ImportColumn::make('meta_decimal')
                ->label('Meta Decimal')
                ->numeric()
                ->ignoreBlankState()
                ->rules(['nullable', 'max:8'])
                ->examples(['Sample Meta Decimal 1', 'Sample Meta Decimal 2'])
                ->exampleHeader('Meta Decimal'),

            ImportColumn::make('meta_date')
                ->label('Meta Date')
                ->ignoreBlankState()
                ->rules(['nullable', 'max:255', 'date'])
                ->examples(['2024-01-01', '2024-12-31'])
                ->exampleHeader('Meta Date'),

            ImportColumn::make('character')
                ->label('nama_watak')
                ->relationship(resolveUsing: ['nama_watak'])
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['nullable', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('nama_watak'),
        ];
    }

    /**
     * Resolve which record this imported row maps to (generated custom logic).
     * @return  ?Induk  Resolved record instance.
     */
    public function resolveRecord(): ?Induk
    {
    return new Induk();
    }

    /**
     * Notification body shown when the import finishes.
     *
     * @param  Import  $import  The completed import job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Import $import): string
    {
        $body = 'Your Induks import has completed and ' . Number::format($import->successful_rows) . ' ' . str('row')->plural($import->successful_rows) . ' imported.';

        if ($failedRowsCount = $import->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to import.';
        }

        return $body;
    }
    
    /**
     * Extra options form shown before importing (dry run / update existing).
     * @return  array  Form component definitions.
     */
    public static function getOptionsFormComponents(): array
    {
        return [
            Checkbox::make('updateExisting')
                ->label('Update existing records'),
        ];
    }

}
